// chainDoneDoc is a document whose chain sources have all written their
// namespaces (done): the chain derivation contributes nothing, so any derived
// task for the row must come from the element-attachment input (D-4).
func chainDoneDoc(relPath string) map[string]any {
	doc := baseDoc(relPath)
	doc["sources"] = map[string]any{
		"tv-parser":     map[string]any{"title": "done"},
		"tmdb":          map[string]any{"title": "done"},
		"frame-grabber": map[string]any{"thumbnail": "done"},
	}
	return doc
}

// attach element-only parsers to an item (the D-3 control table, written via
// the store's API lane — the queue is a reader).
func attach(t *testing.T, s *store.Store, itemID string, pluginIDs ...string) {
	t.Helper()
	if err := s.SetItemParsers(context.Background(), itemID, pluginIDs); err != nil {
		t.Fatalf("SetItemParsers %s: %v", itemID, err)
	}
}

// TestQueue_ElementAttachedDrains is element-pages 4.1 (D-4) end to end at the
// queue level: an element-attached local parser (anitomy — undeclared in the tv
// chain, empty auth_mode) derives (item, plugin) work, drains through the SAME
// leases/retry/ledger machinery as the chain, and writes the standard
// namespace/_provenance/_stages trail. A sibling without the attachment gains
// nothing (D-3 sibling isolation).
func TestQueue_ElementAttachedDrains(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putItem(t, s, "i_extra", libID, statusPending, baseDoc("Show/S01E01.mkv"))
	putItem(t, s, "i_sibling", libID, statusPending, baseDoc("Show/S01E02.mkv"))
	attach(t, s, "i_extra", "anitomy")

	anitomy := &succeedSrc{id: "anitomy"}
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{Backoff: time.Millisecond})
	q.resolve = mapResolver{
		"tv-parser": &succeedSrc{id: "tv-parser"},
		"tmdb":      &succeedSrc{id: "tmdb"},
		"anitomy":   anitomy,
	}.resolver()

	if err := q.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer q.Stop()
	q.Notify(ctx, libID)

	it := waitForStatus(t, s, "i_extra", statusReady, 2*time.Second)
	doc := decodeDoc(it.Document)
	sources, _ := doc["sources"].(map[string]any)
	ns, ok := sources["anitomy"].(map[string]any)
	if !ok || ns["title"] != "anitomy" {
		t.Fatalf("sources.anitomy = %v, want the parser's own namespace (standard write shape)", sources["anitomy"])
	}
	prov, _ := doc["_provenance"].(map[string]any)
	p, _ := prov["title"].(map[string]any)
	if p == nil || p["plugin_id"] != "anitomy" {
		t.Fatalf("_provenance.title = %v, want an anitomy provenance entry", prov["title"])
	}
	foundStage := false
	stages, _ := doc["_stages"].([]map[string]any)
	for _, st := range stages {
		if pid, _ := st["plugin_id"].(string); pid == "anitomy" && st["status"] == "ok" {
			foundStage = true
		}
	}
	if !foundStage {
		t.Fatalf("_stages has no ok entry for anitomy: %v", doc["_stages"])
	}

	// Sibling isolation: no attachment -> no anitomy namespace, and anitomy's
	// Match never ran for the sibling (one call total above is i_extra's).
	sib := waitForStatus(t, s, "i_sibling", statusReady, 2*time.Second)
	sibDoc := decodeDoc(sib.Document)
	sibSources, _ := sibDoc["sources"].(map[string]any)
	if _, ok := sibSources["anitomy"]; ok {
		t.Fatalf("sibling gained sources.anitomy (attachment leaked): %v", sibSources)
	}
}

// TestQueue_ElementAttachedDerivation is the derivation half of element-pages
// 4.1/4.2 (D-4 + D-Q1): attachments derive work under the SAME predicate as the
// chain — a local parser queues when its namespace is absent, a CLIENT-locked
// attachment NEVER queues (its declared AuthMode is the lock), ledger cooldown
// applies identically, and siblings are untouched.
func TestQueue_ElementAttachedDerivation(t *testing.T) {
	ctx := context.Background()
	withFixedClock(t, time.Date(2026, 8, 3, 12, 0, 0, 0, time.UTC))
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})

	t.Run("attached_local_parser_derived_when_chain_done", func(t *testing.T) {
		putItem(t, s, "i_att", libID, statusEnriched, chainDoneDoc("Show/S01E01.mkv"))
		attach(t, s, "i_att", "anitomy")
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		found := false
		for _, tk := range tasks {
			if tk.rowID == "i_att" {
				if tk.pluginID != "anitomy" {
					t.Fatalf("unexpected chain task for a chain-done item: %+v", tk)
				}
				found = true
			}
		}
		if !found {
			t.Fatalf("(i_att, anitomy) not derived from the attachment; tasks = %v", pluginIDs(tasks))
		}
	})

	t.Run("attached_CLIENT_source_never_derived", func(t *testing.T) {
		// kinopoisk IS chain-declared with auth_mode CLIENT; the chain is done,
		// so ONLY the attachment path could derive it — and D-Q1 must hold there.
		putItem(t, s, "i_client", libID, statusEnriched, chainDoneDoc("Show/S01E02.mkv"))
		attach(t, s, "i_client", "kinopoisk", "anitomy")
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		for _, tk := range tasks {
			if tk.rowID == "i_client" && tk.pluginID == "kinopoisk" {
				t.Fatalf("CLIENT-locked attachment derived into the queue (D-Q1 broken): %+v", tk)
			}
		}
	})

	t.Run("attachment_cooldown_skips_then_rederives", func(t *testing.T) {
		putItem(t, s, "i_cool_extra", libID, statusEnriched, chainDoneDoc("Show/S01E03.mkv"))
		attach(t, s, "i_cool_extra", "anitomy")
		t0 := now()
		if err := s.RecordFailure(ctx, "i_cool_extra", "anitomy", ledgerExhausted, "boom",
			defaultMaxAttempts, t0.Add(defaultExhaustedCool)); err != nil {
			t.Fatalf("RecordFailure: %v", err)
		}
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		for _, tk := range tasks {
			if tk.rowID == "i_cool_extra" && tk.pluginID == "anitomy" {
				t.Fatalf("attached pair derived within cooldown (loop-safety broken): %+v", tk)
			}
		}
		now = func() time.Time { return t0.Add(defaultExhaustedCool + time.Second) }
		tasks2, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary (post-eligibility): %v", err)
		}
		found := false
		for _, tk := range tasks2 {
			if tk.rowID == "i_cool_extra" && tk.pluginID == "anitomy" {
				found = true
			}
		}
		if !found {
			t.Fatalf("attached pair NOT re-derived after cooldown expired")
		}
	})

	t.Run("sibling_without_attachment_gets_nothing", func(t *testing.T) {
		putItem(t, s, "i_bare", libID, statusEnriched, chainDoneDoc("Show/S01E04.mkv"))
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		for _, tk := range tasks {
			if tk.rowID == "i_bare" {
				t.Fatalf("unattached sibling derived work: %+v", tk)
			}
		}
	})
}

// TestEnrich_Extras is the sync half of element-pages 4.1: Enrich honors the
// element-attached extras — they run after the chain in attachment order through
// the identical per-source path (standard namespace/_provenance/_stages writes),
// and an attached chain-declared plugin is NOT run twice (the chain drives it).
func TestEnrich_Extras(t *testing.T) {
	ctx := context.Background()

	t.Run("extras_run_after_chain_and_write_standard_trail", func(t *testing.T) {
		var order []string
		chain := &fakeSource{id: "tmdb", applies: true, metadata: map[string]any{"title": "T", "year": 1.0}, order: &order}
		anitomy := &fakeSource{id: "anitomy", applies: true, metadata: map[string]any{"romaji": "R"}, order: &order}
		fakes := fakeRegistry{"tmdb": chain, "anitomy": anitomy}
		mod := module.Module{ID: "tv", MediaType: "tv", MetadataSources: []module.MetadataSourceBinding{
			{PluginID: "tmdb", CapabilityID: "default", Priority: 1, Enabled: true},
		}}
		doc := map[string]any{}
		out, status, res, err := enrichDoc(ctx, fakes.resolve, mod, doc, &scannerv1.IdentifyResult{}, runExtras(mod, []string{"anitomy"}))
		if err != nil {
			t.Fatalf("enrichDoc: %v", err)
		}
		if status != statusEnriched {
			t.Fatalf("status = %q, want enriched", status)
		}
		if res.Succeeded != 2 {
			t.Fatalf("Succeeded = %d, want 2 (chain + extra)", res.Succeeded)
		}
		if len(order) != 2 || order[0] != "tmdb" || order[1] != "anitomy" {
			t.Fatalf("Match order = %v, want [tmdb anitomy] (chain first, extras in attachment order)", order)
		}
		sources, _ := out["sources"].(map[string]any)
		if _, ok := sources["anitomy"]; !ok {
			t.Fatalf("sources.anitomy absent after sync enrich: %v", sources)
		}
		prov, _ := out["_provenance"].(map[string]any)
		p, _ := prov["romaji"].(map[string]any)
		if p == nil || p["plugin_id"] != "anitomy" {
			t.Fatalf("_provenance.romaji = %v, want an anitomy entry (standard provenance write)", prov["romaji"])
		}
		stages, _ := out["_stages"].([]map[string]any)
		if len(stages) != 2 {
			t.Fatalf("_stages = %d entries, want 2 (one per source, standard trail)", len(stages))
		}
	})

	t.Run("attached_chain_plugin_not_run_twice", func(t *testing.T) {
		var order []string
		both := &fakeSource{id: "tmdb", applies: true, metadata: map[string]any{"title": "T"}, order: &order}
		fakes := fakeRegistry{"tmdb": both}
		mod := module.Module{ID: "tv", MediaType: "tv", MetadataSources: []module.MetadataSourceBinding{
			{PluginID: "tmdb", CapabilityID: "default", Priority: 1, Enabled: true, AuthMode: "SERVER"},
		}}
		_, _, res, err := enrichDoc(ctx, fakes.resolve, mod, map[string]any{}, &scannerv1.IdentifyResult{}, runExtras(mod, []string{"tmdb"}))
		if err != nil {
			t.Fatalf("enrichDoc: %v", err)
		}
		if res.Succeeded != 1 || len(order) != 1 {
			t.Fatalf("Succeeded = %d, Match calls = %d, want 1/1 (chain-declared attachment must not double-run)", res.Succeeded, len(order))
		}
	})
}
